import test from 'node:test';
import assert from 'node:assert/strict';

import { parseRange } from '../src/parseRange.js';

test('expands an inclusive range', () => {
  assert.deepEqual(parseRange('3-7'), [3, 4, 5, 6, 7]);
});

test('throws on malformed input', () => {
  for (const input of ['', 'abc', '3-', '-7', '3-7-9', '3 - 7', '3.5-7']) {
    assert.throws(() => parseRange(input), /bad range/, `expected "${input}" to be rejected`);
  }
});

test('throws on an inverted range', () => {
  assert.throws(() => parseRange('7-3'), /inverted range/);
});

test('throws when the span is wider than 1000', () => {
  assert.throws(() => parseRange('0-1001'), /range too wide/);
});

test('allows the widest span that fits', () => {
  const values = parseRange('0-1000');
  assert.equal(values.length, 1001);
  assert.equal(values[0], 0);
  assert.equal(values.at(-1), 1000);
});

